1	import { currentUser } from "@/lib/auth";
2	import { MarketingFooter } from "@/components/marketing/MarketingFooter";
3	import { CurrencyProvider } from "@/components/currency/CurrencyContext";
4	import { resolveDisplayCurrency } from "@/lib/currency-display";
5	import { AU_ICONS } from "../_aurora/icons";
6	import { reviewBadgesHtml } from "./ReviewBadges";
7	import { PageRuntime } from "./PageRuntime";
8	import { HeroParticles } from "./HeroParticles";
9	import { APP_URL } from "@/components/marketing/StructuredData";
10	import { crumbs } from "../_seo/meta";
11	import { currencyMeta, ZERO_DECIMAL_CURRENCIES } from "@/lib/currency";
12	import { CurrencyReload } from "./CurrencyReload";
13	import { StableHtml } from "./StableHtml";
14	
15	/**
16	 * One ported design page (generated by tools/nxm/port_pages.py): the design's
17	 * own markup inside `.nxm-p-<slug>`, with the per-request slots filled here —
18	 * nav button and "Log in" by session, real-only review badges — and the live
19	 * footer after it.
20	 */
21	const esc = (s: string) => s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
22	const rocket = `<span class="nxm-rk"><svg class="au-ic" viewBox="0 0 24 24" aria-hidden="true">${AU_ICONS.rocket}</svg></span>`;
23	
24	export async function fillSlots(html: string) {
25	  const user = await currentUser();
26	  const navCta = user
27	    ? `<a class="nxm-btn nxm-sm nxm-navcta" href="/dashboard"><span class="nxm-bt">Open dashboard</span><span class="nxm-arw" aria-hidden="true">→</span></a>`
28	    : `<a class="nxm-btn nxm-sm nxm-navcta au-hov" href="/register">${rocket}<span class="nxm-bt">Deploy a server</span></a>`;
29	  const login = user ? "" : `<a class="nv-login" href="/login">Log in</a>`;
30	  const reviews = await reviewBadgesHtml();
31	  return html
32	    .replaceAll("<!--NXM:NAVCTA-->", navCta)
33	    .replaceAll("<!--NXM:LOGIN-->", login)
34	    .replaceAll("<!--NXM:REVIEWS-->", reviews);
35	}
36	
37	/** Page data slots: `{{nxm:key}}` in the generated markup, filled from the
38	 *  page's loader (app/nxm/_data/<slug>.ts) with real values from the system.
39	 *  Keys ending in `:html` are trusted server-rendered markup; every other
40	 *  value is escaped. An unfilled slot throws: a page never renders with a
41	 *  hole or a stale number where live data belongs. */
42	function fillData(html: string, slots: Record<string, string>) {
43	  const out = html.replace(/\{\{nxm:([a-zA-Z0-9_.:-]+)\}\}/g, (_, key: string) => {
44	    if (!(key in slots)) throw new Error(`nxm: no value for slot "${key}"`);
45	    return key.endsWith(":html") ? slots[key] : esc(slots[key]);
46	  });
47	  return out;
48	}
49	/** The visitor's display currency for the page's own scripts (__nxmMoney). */
50	export function fxFor(code: string, rate: number) {
51	  return { code, rate, symbol: currencyMeta(code).symbol, zero: ZERO_DECIMAL_CURRENCIES.has(code) };
52	}
53	const jsonForScript = (v: unknown) => JSON.stringify(v).replace(/</g, "\\u003c");
54	
55	/** FAQ Q/A pairs straight from the page's own FAQ markup (the Aurora FAQ is
56	 *  `<details><summary>Q</summary><p>A</p></details>`), after slots are filled
57	 *  — so the FAQ rich result always says exactly what the page says. */
58	const text = (h: string) => h.replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&#39;|&rsquo;/g, "'").replace(/&quot;/g, '"').replace(/\s+/g, " ").trim();
59	export function faqFromHtml(html: string) {
60	  const out: { q: string; a: string }[] = [];
61	  // the nav's mobile sheet uses <details> for its menus — never FAQ content
62	  const body = html.replace(/<header\b[\s\S]*?<\/header>/g, "").replace(/<nav\b[\s\S]*?<\/nav>/g, "");
63	  for (const m of body.matchAll(/<details[^>]*>\s*<summary[^>]*>([\s\S]*?)<\/summary>([\s\S]*?)<\/details>/g)) {
64	    const q = text(m[1]), a = text(m[2]);
65	    if (q && a) out.push({ q, a });
66	  }
67	  return out;
68	}
69	
70	/**
71	 * Structured data every page gets: BreadcrumbList from its route, FAQPage
72	 * from its own FAQ markup, plus whatever the page loader adds (Product offers
73	 * from real plans, BlogPosting, SoftwareApplication…). URLs are production
74	 * URLs (APP_URL + route), never the /nxm staging path.
75	 */
76	function jsonLdFor(route: string, html: string, crumbName: string | undefined, extra: object[], given?: { name: string; path: string }[]) {
77	  const trail = given?.length ? [{ name: "Home", path: "/" }, ...given] : crumbs(route, crumbName);
78	  const blocks: object[] = [];
79	  if (route !== "/" && trail.length > 1) {
80	    blocks.push({
81	      "@context": "https://schema.org", "@type": "BreadcrumbList",
82	      itemListElement: trail.map((c, i) => ({ "@type": "ListItem", position: i + 1, name: c.name, item: APP_URL + (c.path === "/" ? "" : c.path) })),
83	    });
84	  }
85	  const faq = faqFromHtml(html);
86	  if (faq.length) {
87	    blocks.push({
88	      "@context": "https://schema.org", "@type": "FAQPage",
89	      mainEntity: faq.map((f) => ({ "@type": "Question", name: f.q, acceptedAnswer: { "@type": "Answer", text: f.a } })),
90	    });
91	  }
92	  return [...blocks, ...extra];
93	}
94	
95	/** The design page's own <body> attributes, carried on the page wrapper. */
96	export type BodyAttrs = { cls: string; style: string; data: Record<string, string> };
97	function wrapperProps(slug: string, attrs?: BodyAttrs) {
98	  const style: Record<string, string> = {};
99	  for (const decl of (attrs?.style ?? "").split(";")) {
100	    const i = decl.indexOf(":");
101	    if (i > 0) style[decl.slice(0, i).trim()] = decl.slice(i + 1).trim();
102	  }
103	  const data: Record<string, string> = {};
104	  for (const [k, v] of Object.entries(attrs?.data ?? {})) data[`data-${k}`] = v;
105	  return { className: `nxm-p nxm-p-${slug}${attrs?.cls ? " " + attrs.cls : ""}`, style: style as React.CSSProperties, ...data };
106	}
107	
108	export async function NxmPage({ slug, route, body, attrs, particles, slots, data, jsonLd, crumb, trail }: {
109	  slug: string; route: string; body: string; attrs?: BodyAttrs; particles?: { from: string; to: string };
110	  slots?: Record<string, string>; data?: unknown; jsonLd?: object[]; crumb?: string; trail?: { name: string; path: string }[];
111	}) {
112	  const [filled, display] = await Promise.all([fillSlots(body), resolveDisplayCurrency()]);
113	  const page = fillData(filled, slots ?? {});
114	  const ld = jsonLdFor(route, page, crumb, jsonLd ?? [], trail);
115	  const html = page
116	    + (data === undefined ? "" : `<script type="application/json" id="nxm-data">${jsonForScript(data)}</script>`)
117	    + `<script type="application/json" id="nxm-fx">${jsonForScript(fxFor(display.currency, display.rate))}</script>`
118	    + ld.map((b) => `<script type="application/ld+json">${jsonForScript(b)}</script>`).join("");
119	  return (
120	    <>
121	      <StableHtml {...wrapperProps(slug, attrs)} html={html} />
122	      <CurrencyProvider initialCurrency={display.currency} rates={display.rates}>
123	        <MarketingFooter />
124	        <CurrencyReload initial={display.currency} />
125	      </CurrencyProvider>
126	      <PageRuntime slug={slug} />
127	      {particles && <HeroParticles slug={slug} from={particles.from} to={particles.to} />}
128	    </>
129	  );
130	}
