1	import type { Metadata } from "next";
2	import { currentUser } from "@/lib/auth";
3	import { MarketingFooter } from "@/components/marketing/MarketingFooter";
4	import { CurrencyProvider } from "@/components/currency/CurrencyContext";
5	import { resolveDisplayCurrency } from "@/lib/currency-display";
6	import { AU_ICONS } from "./_aurora/icons";
7	import { reviewBadgesHtml } from "./_components/ReviewBadges";
8	import { preload } from "react-dom";
9	import { HOME_SCRIPT } from "./_home/script";
10	import { AFTER_MAIN_HTML, HEADER_HTML, MAIN_HTML, PRE_HEADER_HTML } from "./_home/content";
11	import { HomeScript } from "./_home/HomeScript";
12	import "./home.css";
13	import { nxmMetadata } from "./_seo/meta";
14	import { load } from "./_data/home";
15	import { initDisplayFx } from "./_data/lib";
16	import { CurrencyReload } from "./_components/CurrencyReload";
17	import { StableHtml } from "./_components/StableHtml";
18	
19	/**
20	 * The new homepage: the design package's own markup, CSS and script
21	 * (generated by tools/nxm/port_home.py — never hand-edit _home/content.ts or
22	 * home.css) with the owner's identity changes filled in here per request:
23	 * the nav button, "Log in" (signed out only) and the real-only review badges,
24	 * plus the real catalogue data (app/nxm/_data/home.ts): `{{nxm:key}}` slots in
25	 * the markup and the page data the design script reads as `__NXM`.
26	 */
27	export const dynamic = "force-dynamic";
28	export async function generateMetadata(): Promise<Metadata> {
29	  return nxmMetadata("/");
30	}
31	
32	const esc = (s: string) => s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
33	const jsonForScript = (v: unknown) => JSON.stringify(v).replace(/</g, "\\u003c");
34	
35	/** Same contract as NxmPage: `{{nxm:key}}` slots, `:html` keys trusted
36	 *  server-rendered markup, everything else escaped; an unfilled slot throws,
37	 *  so the page never renders a hole or a stale number where live data belongs. */
38	function fillData(html: string, slots: Record<string, string>) {
39	  return html.replace(/\{\{nxm:([a-zA-Z0-9_.:-]+)\}\}/g, (_, key: string) => {
40	    if (!(key in slots)) throw new Error(`nxm home: no value for slot "${key}"`);
41	    return key.endsWith(":html") ? slots[key] : esc(slots[key]);
42	  });
43	}
44	
45	const INLINE_HOME =
46	  "(function(){var h=document.querySelector('.nxm-home');if(!h||h.dataset.homeMounted)return;h.dataset.homeMounted='1';" +
47	  "document.documentElement.classList.add('nxm-home-root');})();\n" + HOME_SCRIPT.replace(/<\/script/gi, "<\\/script");
48	
49	const rocket = `<span class="nxm-rk"><svg class="au-ic" viewBox="0 0 24 24" aria-hidden="true">${AU_ICONS.rocket}</svg></span>`;
50	
51	export default async function NxmHome() {
52	  // the globe's WebGL library starts downloading with the HTML
53	  preload("/nxm/three.min.js", { as: "script" });
54	  await initDisplayFx(); // prices in the visitor's currency, resolved before the loader formats any
55	  const [user, display, d] = await Promise.all([currentUser(), resolveDisplayCurrency(), load()]);
56	
57	  const navCta = user
58	    ? `<a class="nxm-btn nxm-sm nxm-navcta" href="/dashboard"><span class="nxm-bt">Open dashboard</span><span class="nxm-arw" aria-hidden="true">→</span></a>`
59	    : `<a class="nxm-btn nxm-sm nxm-navcta au-hov" href="/register">${rocket}<span class="nxm-bt">Deploy a server</span></a>`;
60	
61	  const reviews = await reviewBadgesHtml();
62	
63	  const login = user ? "" : `<a class="nv-login" href="/login">Log in</a>`;
64	  const header = HEADER_HTML.replaceAll("<!--NXM:NAVCTA-->", navCta).replaceAll("<!--NXM:LOGIN-->", login);
65	  const main = fillData(MAIN_HTML.replace("<!--NXM:REVIEWS-->", reviews), d.slots)
66	    + `<script type="application/json" id="nxm-data">${jsonForScript(d.data)}</script>`
67	    + d.jsonLd.map((b) => `<script type="application/ld+json">${jsonForScript(b)}</script>`).join("");
68	
69	  return (
70	    <>
71	      <div className="nxm-home">
72	        <StableHtml html={PRE_HEADER_HTML + header} />
73	        <StableHtml as="main" id="main" html={main} />
74	        {AFTER_MAIN_HTML && <div dangerouslySetInnerHTML={{ __html: AFTER_MAIN_HTML }} />}
75	        {/* The design's script runs as soon as the markup above is parsed — not
76	            after React hydrates the whole page — so the hero's intro plays once,
77	            in order, instead of the title re-animating and pieces popping in a
78	            second late. HomeScript still runs it on client-side navigation. */}
79	        <script dangerouslySetInnerHTML={{ __html: INLINE_HOME }} />
80	      </div>
81	      <CurrencyProvider initialCurrency={display.currency} rates={display.rates}>
82	        <MarketingFooter />
83	        <CurrencyReload initial={display.currency} />
84	      </CurrencyProvider>
85	      <HomeScript />
86	    </>
87	  );
88	}
