1	"use client";
2	
3	import Link from "next/link";
4	import { useEffect, useState } from "react";
5	import type { CompStatus } from "@/lib/monitoring";
6	import { OVERALL_TITLE, STATUS_DOT } from "@/lib/status-copy";
7	
8	/**
9	 * The footer's platform-status line.
10	 *
11	 * This used to be the literal string "All systems operational" beside a pulsing
12	 * green dot, hardcoded into the footer of every marketing page. It consulted
13	 * nothing. During a real outage the whole site went on insisting everything was
14	 * fine — the same class of defect as a job reporting success it never verified.
15	 *
16	 * Why a client component rather than `await getHealth()` in the footer: every
17	 * marketing page is prerendered to static HTML at build time (see
18	 * `.next/server/app/*.html`), so a server-side read would freeze whatever the
19	 * platform looked like during `next build` into the footer forever — a fresher
20	 * lie, not a fix. Fetching `/api/health` after mount is the only way this line
21	 * can be true on a page that is otherwise static.
22	 *
23	 * Until the probe answers — and if it fails, or the browser is offline — we
24	 * render the link with a neutral dot and the word "Status" and make NO claim.
25	 * Saying nothing is the correct output when nothing is known.
26	 */
27	
28	type Health = {
29	  web?: { status: CompStatus };
30	  db?: { status: CompStatus };
31	  worker?: { status: CompStatus };
32	  proxmox?: { status: CompStatus };
33	};
34	
35	/** Worst-of roll-up, mirroring `overallStatus()` in lib/monitoring. */
36	function rollUp(h: Health): CompStatus | null {
37	  const all = [h.web?.status, h.db?.status, h.worker?.status, h.proxmox?.status];
38	  if (all.some((s) => s === undefined)) return null;
39	  if (all.includes("down")) return "down";
40	  if (all.includes("degraded")) return "degraded";
41	  return "operational";
42	}
43	
44	export function FooterStatus() {
45	  const [status, setStatus] = useState<CompStatus | null>(null);
46	
47	  useEffect(() => {
48	    let alive = true;
49	    // /api/health answers a coarse, secret-free status and caches ~15s in
50	    // process, so one fetch per page view costs the platform almost nothing.
51	    // A 503 body is still a valid report ("db down"), so parse it either way.
52	    fetch("/api/health", { cache: "no-store" })
53	      .then((r) => r.json())
54	      .then((d) => {
55	        if (alive && d && typeof d === "object") setStatus(rollUp(d as Health));
56	      })
57	      .catch(() => {
58	        /* unreachable — keep the neutral "Status" line rather than guessing */
59	      });
60	    return () => {
61	      alive = false;
62	    };
63	  }, []);
64	
65	  return (
66	    <Link
67	      href="/status"
68	      className="flex items-center gap-2 text-xs transition-colors hover:text-slate-300"
69	    >
70	      <span
71	        className={`h-2 w-2 rounded-full ${
72	          status ? `${STATUS_DOT[status]} animate-pulse-dot` : "bg-slate-600"
73	        }`}
74	      />
75	      {status ? OVERALL_TITLE[status] : "Status"}
76	    </Link>
77	  );
78	}
