/* ═══════════════════════════════════════════════════════════════════════════
   NXEON MARKETING — identity layer (tokens + components ported from the live
   site and the portal). Owner's identity spec: /root/nxeon-marketing-v1/IDENTITY-SPEC.md

   Everything that can be nested lives under `.nxm`, the wrapper rendered only
   by app/nxm/layout.tsx, so none of it can reach the portal
   (`:root:has(.nx-shell-root)`), admin, or the live marketing site. Every
   class here is `nxm-` prefixed: the portal and live site already own `.btn`,
   `.btn-primary`, `.card`, `.glass`, `.card-glass`, and reusing those names —
   even scoped — is how "buttons look different on the other site" bugs start.

   @property and @keyframes are hoisted to top level on purpose: nested inside
   a style rule they are silently dropped (CLAUDE.md, the 34-frozen-animations
   incident). Their names are nxm- prefixed for the same collision reason.
   ═══════════════════════════════════════════════════════════════════════════ */

@property --nxm-rim { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
@property --nxm-orbit { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
@keyframes nxm-rim-spin { from { --nxm-rim: 0deg; } to { --nxm-rim: 360deg; } }
@keyframes nxm-orbit { to { --nxm-orbit: 360deg; } }
@keyframes nxm-sweep { 0% { transform: translateX(-130%) skewX(-12deg); } 100% { transform: translateX(130%) skewX(-12deg); } }

.nxm {
  /* ── Aurora palette ─────────────────────────────────────────────── */
  --bg: #060913; --bg-2: #080D1C;
  --surface: #0C1328; --surface-2: #111A34; --surface-3: #16213F;
  --line: rgba(138,160,255,.12); --line-2: rgba(138,160,255,.2); --line-3: rgba(160,180,255,.34);
  --ink: #E9EDFA; --ink-2: #B6BEDA; --muted: #8792B4;
  --blue: #1463FF; --blue-hi: #3B7DFF; --link: #86A8FF; --indigo: #4B2EF2;
  --cyan: #3EDCF2; --purple: #7B3AF5; --magenta: #E04BD6; --green: #3FD89A; --amber: #F2B64B;
  --aurora: linear-gradient(90deg, #3EDCF2 0%, #0A66FF 36%, #4B2EF2 68%, #8B3DF5 100%);

  /* ── Type: Geist + Geist Mono, loaded site-wide by app/layout.tsx ──
     The design package's Aurora CSS reads --f-display / --f-body /
     --f-mono, so pointing those at Geist swaps the whole kit's face. */
  --f-display: var(--font-nx-sans), ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --f-body: var(--font-nx-sans), ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --f-mono: var(--font-nx-mono), ui-monospace, SFMono-Regular, Menlo, monospace;

  color-scheme: dark;
  min-height: 100dvh;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--f-body);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;

  & a { color: var(--link); }
  & :focus-visible { outline: 2px solid var(--cyan); outline-offset: 3px; }

  /* ═════════════ BUTTONS ═════════════ */

  /* PRIMARY — the live site's `.btn-deploy`, which the portal's own `.btn` is
     a copy of (its comment says so): one component, two colourings. Pill on a
     4-stop gradient that slides on hover, a one-shot shimmer sweep, a 1px lift
     and an arrow nudge — the original motion, retinted to Aurora stops.
     Owner: deploy/buy CTAs carry Aurora's animated rocket (`.au-hov` on the
     button makes the icon play on hover). */
  & .nxm-btn {
    position: relative; overflow: hidden; isolation: isolate;
    display: inline-flex; align-items: center; justify-content: center; gap: 9px;
    height: 46px; padding: 0 22px; border: 0; border-radius: 999px; cursor: pointer;
    font: 700 15px/1 var(--f-body); color: #fff; text-decoration: none; white-space: nowrap;
    background-image: linear-gradient(110deg, #7B3AF5, #1463FF, #3EDCF2, #7B3AF5);
    background-size: 220% 100%; background-position: 0% 0;
    box-shadow: 0 8px 26px -8px rgba(75,46,242,.6), inset 0 1px 0 0 rgba(255,255,255,.18);
    transition: transform .2s ease, box-shadow .2s ease, background-position .6s ease;
  }
  & .nxm-btn::before {
    content: ""; position: absolute; inset-block: 0; left: 0; width: 60%; z-index: -1;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,.38), transparent);
    transform: translateX(-130%) skewX(-12deg); pointer-events: none;
  }
  & .nxm-btn:hover {
    transform: translateY(-1px); background-position: 100% 0;
    box-shadow: 0 12px 34px -8px rgba(75,46,242,.75), inset 0 1px 0 0 rgba(255,255,255,.25);
  }
  & .nxm-btn:hover::before { animation: nxm-sweep .75s ease; }
  & .nxm-btn:active { transform: translateY(0); }

