import { useEffect, useRef } from "react";
import { useCurrency } from "@/components/currency/CurrencyContext";

/**
 * The new pages render their prices on the server in the visitor's currency.
 * When the visitor picks another currency in the footer switcher (which saves
 * the `nx_currency` cookie), reload so the server re-renders every price in it.
 */
export function CurrencyReload({ initial }: { initial: string }) {
  const { currency } = useCurrency();
  const first = useRef(initial);
  useEffect(() => {
    if (currency && currency !== first.current) window.location.reload();
  }, [currency]);
  return null;
}

