import Link from "next/link";
import Image from "next/image";
import { getSetting, getSettingBool, SETTINGS_DEFAULTS } from "@/lib/settings";
import { NxmNewsletterForm } from "./NxmNewsletterForm";
import { NxmFooterStatus } from "./NxmFooterStatus";

/**
 * The new site's own footer — the design package's markup (source/part2.html
 * `<footer class="footer" id="company">`, classes `fgrid`/`fbrand`/`fcol`/
 * `fbottom`/`socials`) restyled with Aurora tokens (nxm.css, the `.footer`
 * rules under the shared `.nxm` scope) and wired to real data, replacing the
 * live site's `<MarketingFooter />` that every /nxm page rendered verbatim
 * until now (old Tailwind theme, no Aurora anywhere in it — the one visibly
 * "old site" thing left under an otherwise fully restyled page).
 *
 * The design's own footer has no subscribe form and placeholder `#anchor`
 * links — those are the two things this component adds/fixes on top of the
 * design's own classes: `NxmNewsletterForm` posts to the real `subscribe()`
 * server action (lib/actions-newsletter.ts, same one the live footer's box
 * calls), and every nav link below points at a real /nxm route from
 * `app/nxm/_seo/registry.ts` / `tools/nxm/nxmlib.py`'s ROUTES — never a dead
 * `#anchor`. Items from the design's nav with no /nxm equivalent yet (CLI,
 * Infrastructure, Partners, Careers) are dropped rather than faked.
 *
 * `.container` and `.logo` from the design are NOT reused here even though
 * the design's footer uses them: both collide with real classes elsewhere
 * (Tailwind's own `.container` utility; the ported pages' per-page `.logo`
 * rules) that are only cancelled *inside* `.nxm-home`/`.nxm-p` — and this
 * footer renders as a SIBLING of those wrappers (see app/nxm/page.tsx and
 * NxmPage.tsx), not a descendant, so it gets none of that cancelling.
 * `.footer-in` / `.fbrand-mark` are this component's own names for the same
 * two roles.
 */

const PRODUCTS = [
  { label: "VPS Hosting", href: "/nxm/vps" },
  { label: "Game Servers", href: "/nxm/game-servers" },
  { label: "Web Hosting", href: "/nxm/web-hosting" },
  { label: "Business Email", href: "/nxm/business-email" },
  { label: "Domains", href: "/nxm/domains" },
];

// The design's Developers column also lists "CLI" and "Infrastructure" —
// dropped, no /nxm route exists for either yet.
const DEVELOPERS = [
  { label: "API", href: "/nxm/developers" },
  { label: "Documentation", href: "/nxm/docs" },
  { label: "Status", href: "/nxm/status" },
];

const RESOURCES = [
  { label: "NxLabs", href: "/nxm/mods" },
  { label: "Blog", href: "/nxm/blog" },
  { label: "Guides", href: "/nxm/help" },
  { label: "Support", href: "/nxm/contact" },
  { label: "Creator Program", href: "/nxm/affiliate" },
];

// The design's Company column also lists "Partners" and "Careers" — dropped,
// no /nxm route exists for either. Acceptable Use / SLA are added on top of
// the design's own 4 items (About/Contact/Terms/Privacy): real, already-live
// legal routes (tools/nxm/routes/legal.json) worth being crawlable from here.
const COMPANY = [
  { label: "About", href: "/nxm/about" },
  { label: "Contact", href: "/nxm/contact" },
  { label: "Terms", href: "/nxm/legal/terms" },
  { label: "Privacy", href: "/nxm/legal/privacy" },
  { label: "Acceptable Use", href: "/nxm/legal/aup" },
  { label: "SLA", href: "/nxm/legal/sla" },
];

const COLUMNS: { id: string; title: string; links: { label: string; href: string }[] }[] = [
  { id: "f-products", title: "Products", links: PRODUCTS },
  { id: "f-dev", title: "Developers", links: DEVELOPERS },
  { id: "f-res", title: "Resources", links: RESOURCES },
  { id: "f-co", title: "Company", links: COMPANY },
];

export async function NxmFooter() {
  const [newsletterEnabled, brandNameRaw, taglineRaw, discord, x, github, youtube] = await Promise.all([
    getSettingBool("feature_newsletter", true),
    getSetting("brand_name"),
    getSetting("brand_tagline"),
    getSetting("social_discord", ""),
    getSetting("social_twitter", ""),
    getSetting("social_github", ""),
    getSetting("social_youtube", ""),
  ]);
  const brandName = brandNameRaw.trim() || SETTINGS_DEFAULTS.brand_name;
  const tagline = taglineRaw.trim() || SETTINGS_DEFAULTS.brand_tagline;

  // Discord/X/GitHub/YouTube, matching the design's own social row — only
  // rendered when an operator actually set the URL (same "no dead/fake link"
  // discipline as the rest of this project; the live MarketingFooter applies
  // it too, just to a different four platforms).
  const socials = [
    { key: "discord", label: "Discord", href: discord.trim() },
    { key: "x", label: "X", href: x.trim() },
    { key: "github", label: "GitHub", href: github.trim() },
    { key: "youtube", label: "YouTube", href: youtube.trim() },
  ].filter((s) => /^https?:\/\//i.test(s.href));

  const year = new Date().getFullYear();

  return (
    <footer className="footer" id="company">
      <div className="footer-in">
        <div className="fgrid">
          <div className="fbrand">
            <Link href="/nxm" className="fbrand-mark" aria-label={`${brandName} home`}>
              <Image src="/logo.png" alt={brandName} width={157} height={26} priority={false} />
            </Link>
            <p>{tagline}</p>

            {socials.length > 0 && (
              <div className="socials" aria-label={`${brandName} on social media`}>
                {socials.map((s) => (
                  <a key={s.key} href={s.href} target="_blank" rel="noopener noreferrer me" aria-label={`${brandName} on ${s.label}`}>
                    {s.label}
                  </a>
                ))}
              </div>
            )}

            {newsletterEnabled && <NxmNewsletterForm />}
          </div>

          {COLUMNS.map((col) => (
            <nav className="fcol" aria-labelledby={col.id} key={col.id}>
              <h2 id={col.id}>{col.title}</h2>
              <ul>
                {col.links.map((l) => (
                  <li key={l.href}>
                    <Link href={l.href}>{l.label}</Link>
                  </li>
                ))}
              </ul>
            </nav>
          ))}
        </div>

        <div className="fbottom">
          <span>
            &copy; {year} {brandName}. All rights reserved.
          </span>
          <NxmFooterStatus />
        </div>
      </div>
    </footer>
  );
}

