  @media (prefers-reduced-motion: reduce) {
    & .nxm-btn, & .nxm-btn:hover, & .nxm-rim, & .nxm-glassbtn { transition: none; transform: none; }
    & .nxm-btn:hover::before, & :is(.nxm-rim, .nxm-glassbtn):hover::after { animation: none; }
    & :is(.nxm-btn, .nxm-rim, .nxm-glassbtn):hover .nxm-arw { transform: none; }
    & .nxm-lgc, & .nxm-lgc-glow { animation: none; }
  }
}

input.new_string:
  @media (prefers-reduced-motion: reduce) {
    & .nxm-btn, & .nxm-btn:hover, & .nxm-rim, & .nxm-glassbtn { transition: none; transform: none; }
    & .nxm-btn:hover::before, & :is(.nxm-rim, .nxm-glassbtn):hover::after { animation: none; }
    & :is(.nxm-btn, .nxm-rim, .nxm-glassbtn):hover .nxm-arw { transform: none; }
    & .nxm-lgc, & .nxm-lgc-glow { animation: none; }
  }

  /* ═════════════ FOOTER (app/nxm/_components/NxmFooter.tsx) ═════════════
     The design's own footer (source/part2.html, `<footer class="footer"
     id="company">`) is stripped from every ported page by
     tools/nxm/port_pages.py / port_home.py and replaced by NxmFooter — real
     nav (app/nxm/_seo registry routes), the real subscribe() action, the real
     /api/health status and real social settings, in the design's own classes
     (footer/fgrid/fbrand/fcol/fbottom/socials) restyled with Aurora tokens.
     Nested under `.nxm` (not `:is(.nxm-home, .nxm-p)`) because the footer
     renders as a SIBLING of `.nxm-home`/`.nxm-p`, not a descendant (see
     app/nxm/page.tsx, NxmPage.tsx) — `.nxm` is the one wrapper both scopes
     and the footer all sit inside, so nesting it here is what makes one CSS
     block work on every page. `.container` and `.logo` from the design are
     deliberately NOT reused: both collide with real classes (Tailwind's own
     `.container` utility; the ported pages' per-page `.logo` rules) that are
     only cancelled *inside* `.nxm-home`/`.nxm-p` (see "CLASS-NAME COLLISIONS"
     below) — this footer gets none of that cancelling, so `.footer-in` /
     `.fbrand-mark` stand in for those two roles instead. */
  & .footer { border-top: 1px solid var(--line); padding: 80px 0 calc(40px + env(safe-area-inset-bottom,0px)); background: var(--bg-2); }
  & .footer-in { max-width: 1240px; margin-inline: auto; padding-inline: clamp(16px, 4vw, 40px); }
  & .fgrid { display: grid; grid-template-columns: minmax(0,1.5fr) repeat(4, minmax(0,1fr)); gap: 40px; }
  & .fbrand-mark { display: flex; align-items: center; gap: 10px; color: var(--ink); text-decoration: none; min-height: 44px; }
  & .fbrand-mark img { height: 26px; width: auto; display: block; }
  & .fbrand p { color: var(--muted); max-width: 30ch; margin: 18px 0 22px; font-size: .95rem; }
  & .socials { display: flex; gap: 6px; flex-wrap: wrap; }
  & .socials a { color: var(--ink-2); text-decoration: none; font-size: .88rem; padding: 8px 12px; border: 1px solid var(--line); border-radius: 9px; min-height: 40px; display: inline-flex; align-items: center; }
  & .socials a:hover { border-color: var(--line-2); color: var(--ink); }
  & .fcol h2 { font: 600 .92rem var(--f-body); color: var(--ink); margin: 6px 0 16px; }
  & .fcol ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 4px; }
  & .fcol a { color: var(--muted); text-decoration: none; font-size: .94rem; display: inline-flex; min-height: 32px; align-items: center; }
  & .fcol a:hover { color: var(--ink); }
  & .fbottom { display: flex; justify-content: space-between; align-items: center; gap: 20px; flex-wrap: wrap; margin-top: 64px; padding-top: 24px; border-top: 1px solid var(--line); color: var(--muted); font-size: .88rem; }
  & .fbottom a { color: var(--ink-2); text-decoration: none; display: inline-flex; align-items: center; gap: 9px; }
  & .fbottom a:hover { color: var(--ink); }
  & .fbottom .dot { width: 7px; height: 7px; border-radius: 50%; flex: none; background: var(--muted); }
  & .fbottom .dot.live { background: var(--green); }
  & .fbottom .dot.warn { background: var(--amber); }
  & .fbottom .dot.bad { background: #FF6A8A; }

  /* Footer newsletter — the design's own footer has no subscribe form to
     restyle, so this is a minimal addition in the same token language.
     NxmNewsletterForm calls the real subscribe() server action. */
  & .nxm-foot-nl { margin-top: 22px; max-width: 30ch; }
  & .nxm-foot-nlf { display: flex; gap: 8px; }
  & .nxm-foot-nlf input { flex: 1; min-width: 0; height: 42px; padding: 0 14px; border-radius: 10px; border: 1px solid var(--line-2); background: var(--surface); color: var(--ink); font: 500 .88rem var(--f-body); outline: none; }
  & .nxm-foot-nlf input::placeholder { color: var(--muted); }
  & .nxm-foot-nlf input:focus { border-color: var(--line-3); }
  & .nxm-foot-nlmsg { margin: 8px 0 0; font-size: .84rem; }
  & .nxm-foot-nlmsg.ok { color: var(--green); }
  & .nxm-foot-nlmsg.err { color: #FF6A8A; }

  @media (max-width: 1080px) { & .fgrid { grid-template-columns: repeat(4, minmax(0,1fr)); } & .fbrand { grid-column: 1 / -1; } }
  @media (max-width: 700px) { & .fgrid { grid-template-columns: 1fr 1fr; } & .nxm-foot-nl { max-width: none; } }
}

