1	import type { Metadata } from "next";
2	import { currentUser } from "@/lib/auth";
3	import { getLatestPost } from "@/lib/blog";
4	import { MarketingFooter } from "@/components/marketing/MarketingFooter";
5	import { CurrencyProvider } from "@/components/currency/CurrencyContext";
6	import { resolveDisplayCurrency } from "@/lib/currency-display";
7	import { AU_ICONS } from "./_aurora/icons";
8	import { reviewBadgesHtml } from "./_components/ReviewBadges";
9	import { preload } from "react-dom";
10	import { HOME_SCRIPT } from "./_home/script";
11	import { AFTER_MAIN_HTML, HEADER_HTML, MAIN_HTML, PRE_HEADER_HTML } from "./_home/content";
12	import { HomeScript } from "./_home/HomeScript";
13	import "./home.css";
14	import { nxmMetadata } from "./_seo/meta";
15	import { load } from "./_data/home";
16	import { initDisplayFx } from "./_data/lib";
17	import { CurrencyReload } from "./_components/CurrencyReload";
18	import { StableHtml } from "./_components/StableHtml";
19	import { NXM_BASE, categoryLabel, readLabel } from "./_data/blog-shared";
20	
21	/**
22	 * The new homepage: the design package's own markup, CSS and script
23	 * (generated by tools/nxm/port_home.py — never hand-edit _home/content.ts or
24	 * home.css) with the owner's identity changes filled in here per request:
25	 * the nav button, "Log in" (signed out only) and the real-only review badges,
26	 * plus the real catalogue data (app/nxm/_data/home.ts): `{{nxm:key}}` slots in
27	 * the markup and the page data the design script reads as `__NXM`.
28	 */
29	export const dynamic = "force-dynamic";
30	export async function generateMetadata(): Promise<Metadata> {
31	  return nxmMetadata("/");
32	}
33	
34	const esc = (s: string) => s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
35	const jsonForScript = (v: unknown) => JSON.stringify(v).replace(/</g, "\\u003c");
36	
37	/** Same contract as NxmPage: `{{nxm:key}}` slots, `:html` keys trusted
38	 *  server-rendered markup, everything else escaped; an unfilled slot throws,
39	 *  so the page never renders a hole or a stale number where live data belongs. */
40	function fillData(html: string, slots: Record<string, string>) {
41	  return html.replace(/\{\{nxm:([a-zA-Z0-9_.:-]+)\}\}/g, (_, key: string) => {
42	    if (!(key in slots)) throw new Error(`nxm home: no value for slot "${key}"`);
43	    return key.endsWith(":html") ? slots[key] : esc(slots[key]);
44	  });
45	}
46	
47	const INLINE_HOME =
48	  "(function(){var h=document.querySelector('.nxm-home');if(!h||h.dataset.homeMounted)return;h.dataset.homeMounted='1';" +
49	  "document.documentElement.classList.add('nxm-home-root');})();\n" + HOME_SCRIPT.replace(/<\/script/gi, "<\\/script");
50	
51	const rocket = `<span class="nxm-rk"><svg class="au-ic" viewBox="0 0 24 24" aria-hidden="true">${AU_ICONS.rocket}</svg></span>`;
52	
53	/** Same "Latest guide" fix as app/nxm/_components/NxmPage.tsx — see there. */
54	async function latestGuideHtml(): Promise<string> {
55	  try {
56	    const post = await getLatestPost();
57	    if (!post) return "";
58	    const href = `${NXM_BASE}/blog/${encodeURIComponent(post.slug)}`;
59	    return `<a class="nv-post" href="${esc(href)}"><span class="nv-pk">Latest guide · ${esc(categoryLabel(post.category))}</span><b>${esc(post.title)}</b><small>${esc(readLabel(post.body))}</small><span>Read the guide →</span></a>`;
60	  } catch {
61	    return "";
62	  }
63	}
64	
65	export default async function NxmHome() {
66	  // the globe's WebGL library starts downloading with the HTML
67	  preload("/nxm/three.min.js", { as: "script" });
68	  await initDisplayFx(); // prices in the visitor's currency, resolved before the loader formats any
69	  const [user, display, d] = await Promise.all([currentUser(), resolveDisplayCurrency(), load()]);
70	
71	  const navCta = user
72	    ? `<a class="nxm-btn nxm-sm nxm-navcta" href="/dashboard"><span class="nxm-bt">Open dashboard</span><span class="nxm-arw" aria-hidden="true">→</span></a>`
73	    : `<a class="nxm-btn nxm-sm nxm-navcta au-hov" href="/register">${rocket}<span class="nxm-bt">Deploy a server</span></a>`;
74	
75	  const [reviews, latestPost] = await Promise.all([reviewBadgesHtml(), latestGuideHtml()]);
76	
77	  const login = user ? "" : `<a class="nv-login" href="/login">Log in</a>`;
78	  const header = HEADER_HTML.replaceAll("<!--NXM:NAVCTA-->", navCta).replaceAll("<!--NXM:LOGIN-->", login).replaceAll("<!--NXM:LATESTPOST-->", latestPost);
79	  const main = fillData(MAIN_HTML.replace("<!--NXM:REVIEWS-->", reviews), d.slots)
80	    + `<script type="application/json" id="nxm-data">${jsonForScript(d.data)}</script>`
81	    + d.jsonLd.map((b) => `<script type="application/ld+json">${jsonForScript(b)}</script>`).join("");
82	
83	  return (
84	    <>
85	      <div className="nxm-home">
86	        <StableHtml html={PRE_HEADER_HTML + header} />
87	        <StableHtml as="main" id="main" html={main} />
88	        {AFTER_MAIN_HTML && <div dangerouslySetInnerHTML={{ __html: AFTER_MAIN_HTML }} />}
89	        {/* The design's script runs as soon as the markup above is parsed — not
90	            after React hydrates the whole page — so the hero's intro plays once,
91	            in order, instead of the title re-animating and pieces popping in a
92	            second late. HomeScript still runs it on client-side navigation. */}
93	        <script dangerouslySetInnerHTML={{ __html: INLINE_HOME }} />
94	      </div>
95	      <CurrencyProvider initialCurrency={display.currency} rates={display.rates}>
96	        <NxmFooter />
97	        <CurrencyReload initial={display.currency} />
98	      </CurrencyProvider>
99	      <HomeScript />
100	    </>
101	  );
102	}
103

1	import { currentUser } from "@/lib/auth";
2	import { getLatestPost } from "@/lib/blog";
3	import { MarketingFooter } from "@/components/marketing/MarketingFooter";
4	import { CurrencyProvider } from "@/components/currency/CurrencyContext";
5	import { resolveDisplayCurrency } from "@/lib/currency-display";
6	import { AU_ICONS } from "../_aurora/icons";
7	import { reviewBadgesHtml } from "./ReviewBadges";
8	import { PageRuntime } from "./PageRuntime";
9	import { HeroParticles } from "./HeroParticles";
10	import { APP_URL } from "@/components/marketing/StructuredData";
11	import { crumbs } from "../_seo/meta";
12	import { currencyMeta, ZERO_DECIMAL_CURRENCIES } from "@/lib/currency";
13	import { CurrencyReload } from "./CurrencyReload";
14	import { StableHtml } from "./StableHtml";
15	import { NXM_BASE, categoryLabel, readLabel } from "../_data/blog-shared";
16	
17	/**
18	 * One ported design page (generated by tools/nxm/port_pages.py): the design's
19	 * own markup inside `.nxm-p-<slug>`, with the per-request slots filled here —
20	 * nav button and "Log in" by session, real-only review badges — and the live
21	 * footer after it.
22	 */
23	const esc = (s: string) => s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
24	const rocket = `<span class="nxm-rk"><svg class="au-ic" viewBox="0 0 24 24" aria-hidden="true">${AU_ICONS.rocket}</svg></span>`;
25	
26	/**
27	 * Company menu's "Latest guide" teaser (`<!--NXM:LATESTPOST-->`, tools/nxm/
28	 * nxmlib.py nav_slots): the design hardcoded its own example post, which was
29	 * never seeded into the real blog and 404s sitewide (every generated page
30	 * carries this nav). Filled here from the real newest published post instead
31	 * — empty (teaser omitted) if the blog has none, never a stale/broken link.
32	 */
33	async function latestGuideHtml(): Promise<string> {
34	  try {
35	    const post = await getLatestPost();
36	    if (!post) return "";
37	    const href = `${NXM_BASE}/blog/${encodeURIComponent(post.slug)}`;
38	    return `<a class="nv-post" href="${esc(href)}"><span class="nv-pk">Latest guide · ${esc(categoryLabel(post.category))}</span><b>${esc(post.title)}</b><small>${esc(readLabel(post.body))}</small><span>Read the guide →</span></a>`;
39	  } catch {
40	    return "";
41	  }
42	}
43	
44	export async function fillSlots(html: string) {
45	  const user = await currentUser();
46	  const navCta = user
47	    ? `<a class="nxm-btn nxm-sm nxm-navcta" href="/dashboard"><span class="nxm-bt">Open dashboard</span><span class="nxm-arw" aria-hidden="true">→</span></a>`
48	    : `<a class="nxm-btn nxm-sm nxm-navcta au-hov" href="/register">${rocket}<span class="nxm-bt">Deploy a server</span></a>`;
49	  const login = user ? "" : `<a class="nv-login" href="/login">Log in</a>`;
50	  const [reviews, latestPost] = await Promise.all([reviewBadgesHtml(), latestGuideHtml()]);
51	  return html
52	    .replaceAll("<!--NXM:NAVCTA-->", navCta)
53	    .replaceAll("<!--NXM:LOGIN-->", login)
54	    .replaceAll("<!--NXM:REVIEWS-->", reviews)
55	    .replaceAll("<!--NXM:LATESTPOST-->", latestPost);
56	}
57	
58	/** Page data slots: `{{nxm:key}}` in the generated markup, filled from the
59	 *  page's loader (app/nxm/_data/<slug>.ts) with real values from the system.
60	 *  Keys ending in `:html` are trusted server-rendered markup; every other
61	 *  value is escaped. An unfilled slot throws: a page never renders with a
62	 *  hole or a stale number where live data belongs. */
63	function fillData(html: string, slots: Record<string, string>) {
64	  const out = html.replace(/\{\{nxm:([a-zA-Z0-9_.:-]+)\}\}/g, (_, key: string) => {
65	    if (!(key in slots)) throw new Error(`nxm: no value for slot "${key}"`);
66	    return key.endsWith(":html") ? slots[key] : esc(slots[key]);
67	  });
68	  return out;
69	}
70	/** The visitor's display currency for the page's own scripts (__nxmMoney). */
71	export function fxFor(code: string, rate: number) {
72	  return { code, rate, symbol: currencyMeta(code).symbol, zero: ZERO_DECIMAL_CURRENCIES.has(code) };
73	}
74	const jsonForScript = (v: unknown) => JSON.stringify(v).replace(/</g, "\\u003c");
75	
76	/** FAQ Q/A pairs straight from the page's own FAQ markup (the Aurora FAQ is
77	 *  `<details><summary>Q</summary><p>A</p></details>`), after slots are filled
78	 *  — so the FAQ rich result always says exactly what the page says. */
79	const text = (h: string) => h.replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&#39;|&rsquo;/g, "'").replace(/&quot;/g, '"').replace(/\s+/g, " ").trim();
80	export function faqFromHtml(html: string) {
81	  const out: { q: string; a: string }[] = [];
82	  // the nav's mobile sheet uses <details> for its menus — never FAQ content
83	  const body = html.replace(/<header\b[\s\S]*?<\/header>/g, "").replace(/<nav\b[\s\S]*?<\/nav>/g, "");
84	  for (const m of body.matchAll(/<details[^>]*>\s*<summary[^>]*>([\s\S]*?)<\/summary>([\s\S]*?)<\/details>/g)) {
85	    const q = text(m[1]), a = text(m[2]);
86	    if (q && a) out.push({ q, a });
87	  }
88	  return out;
89	}
90	
91	/**
92	 * Structured data every page gets: BreadcrumbList from its route, FAQPage
93	 * from its own FAQ markup, plus whatever the page loader adds (Product offers
94	 * from real plans, BlogPosting, SoftwareApplication…). URLs are production
95	 * URLs (APP_URL + route), never the /nxm staging path.
96	 */
97	function jsonLdFor(route: string, html: string, crumbName: string | undefined, extra: object[], given?: { name: string; path: string }[]) {
98	  const trail = given?.length ? [{ name: "Home", path: "/" }, ...given] : crumbs(route, crumbName);
99	  const blocks: object[] = [];
100	  if (route !== "/" && trail.length > 1) {
101	    blocks.push({
102	      "@context": "https://schema.org", "@type": "BreadcrumbList",
103	      itemListElement: trail.map((c, i) => ({ "@type": "ListItem", position: i + 1, name: c.name, item: APP_URL + (c.path === "/" ? "" : c.path) })),
104	    });
105	  }
106	  const faq = faqFromHtml(html);
107	  if (faq.length) {
108	    blocks.push({
109	      "@context": "https://schema.org", "@type": "FAQPage",
110	      mainEntity: faq.map((f) => ({ "@type": "Question", name: f.q, acceptedAnswer: { "@type": "Answer", text: f.a } })),
111	    });
112	  }
113	  return [...blocks, ...extra];
114	}
115	
116	/** The design page's own <body> attributes, carried on the page wrapper. */
117	export type BodyAttrs = { cls: string; style: string; data: Record<string, string> };
118	function wrapperProps(slug: string, attrs?: BodyAttrs) {
119	  const style: Record<string, string> = {};
120	  for (const decl of (attrs?.style ?? "").split(";")) {
121	    const i = decl.indexOf(":");
122	    if (i > 0) style[decl.slice(0, i).trim()] = decl.slice(i + 1).trim();
123	  }
124	  const data: Record<string, string> = {};
125	  for (const [k, v] of Object.entries(attrs?.data ?? {})) data[`data-${k}`] = v;
126	  return { className: `nxm-p nxm-p-${slug}${attrs?.cls ? " " + attrs.cls : ""}`, style: style as React.CSSProperties, ...data };
127	}
128	
129	export async function NxmPage({ slug, route, body, attrs, particles, slots, data, jsonLd, crumb, trail }: {
130	  slug: string; route: string; body: string; attrs?: BodyAttrs; particles?: { from: string; to: string };
131	  slots?: Record<string, string>; data?: unknown; jsonLd?: object[]; crumb?: string; trail?: { name: string; path: string }[];
132	}) {
133	  const [filled, display] = await Promise.all([fillSlots(body), resolveDisplayCurrency()]);
134	  const page = fillData(filled, slots ?? {});
135	  const ld = jsonLdFor(route, page, crumb, jsonLd ?? [], trail);
136	  const html = page
137	    + (data === undefined ? "" : `<script type="application/json" id="nxm-data">${jsonForScript(data)}</script>`)
138	    + `<script type="application/json" id="nxm-fx">${jsonForScript(fxFor(display.currency, display.rate))}</script>`
139	    + ld.map((b) => `<script type="application/ld+json">${jsonForScript(b)}</script>`).join("");
140	  return (
141	    <>
142	      <StableHtml {...wrapperProps(slug, attrs)} html={html} />
143	      <CurrencyProvider initialCurrency={display.currency} rates={display.rates}>
144	        <NxmFooter />
145	        <CurrencyReload initial={display.currency} />
146	      </CurrencyProvider>
147	      <PageRuntime slug={slug} />
148	      {particles && <HeroParticles slug={slug} from={particles.from} to={particles.to} />}
149	    </>
150	  );
151	}
152

