const { chromium } = require("playwright");

const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/footer";
const BASE = "http://localhost:3033";
const PAGES = ["/nxm", "/nxm/pricing", "/nxm/mods"];
const SIZES = [{ w: 1440, h: 1400, tag: "1440" }, { w: 390, h: 1800, tag: "390" }];

(async () => {
  const browser = await chromium.launch();
  try {
    for (const size of SIZES) {
      const ctx = await browser.newContext({ viewport: { width: size.w, height: size.h } });
      for (const p of PAGES) {
        const page = await ctx.newPage();
        await page.goto(BASE + p, { waitUntil: "networkidle", timeout: 30000 });
        const footer = await page.$("footer.footer");
        if (!footer) {
          console.log(`NO FOOTER FOUND on ${p} @ ${size.tag}`);
        } else {
          await footer.scrollIntoViewIfNeeded();
          await page.waitForTimeout(300); // let the status pill's client fetch resolve
          const name = p.replace(/\//g, "_") + `_${size.tag}.png`;
          await footer.screenshot({ path: `${OUT}/${name}` });
          console.log(`OK ${p} @ ${size.tag} -> ${name}`);
        }
        await page.close();
      }
      await ctx.close();
    }

    // Subscribe form test, full-page 1440 shot, homepage only.
    const ctx = await browser.newContext({ viewport: { width: 1440, height: 1400 } });
    const page = await ctx.newPage();
    const consoleErrors = [];
    page.on("pageerror", (e) => consoleErrors.push(String(e)));
    await page.goto(BASE + "/nxm", { waitUntil: "networkidle", timeout: 30000 });
    const email = `footer-test-${Date.now()}@example.com`;
    await page.fill("#nxm-foot-email", email);
    await page.click(".nxm-foot-nl button[type=submit]");
    await page.waitForTimeout(1500);
    const msg = await page.$eval(".nxm-foot-nlmsg", (el) => el.textContent).catch(() => null);
    console.log("Subscribe result message:", msg);
    console.log("Page errors during subscribe:", consoleErrors);
    await page.screenshot({ path: `${OUT}/subscribe_result.png`, clip: { x: 0, y: 0, width: 1440, height: 900 } }).catch(() => {});
    const footerAfter = await page.$("footer.footer");
    if (footerAfter) await footerAfter.screenshot({ path: `${OUT}/subscribe_result_footer.png` });
    await page.close();
    await ctx.close();
  } finally {
    await browser.close();
  }
})();

