const { chromium } = require("playwright");
const BASE = "http://localhost:3033";

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  page.on("console", (msg) => console.log("CONSOLE:", msg.type(), msg.text()));
  page.on("pageerror", (e) => console.log("PAGEERROR:", String(e)));
  page.on("requestfailed", (r) => console.log("REQFAILED:", r.url(), r.failure()?.errorText));
  page.on("response", (r) => {
    if (r.url().includes("nxm") === false) return;
  });
  await page.goto(BASE + "/nxm", { waitUntil: "load", timeout: 30000 });
  await page.waitForTimeout(800);
  const email = `footer-test-${Date.now()}@example.com`;
  await page.fill("#nxm-foot-email", email);
  const before = await page.$eval(".fbrand", (el) => el.innerHTML);
  console.log("BEFORE:", before.slice(-400));
  await page.click(".nxm-foot-nl button[type=submit]");
  await page.waitForTimeout(2500);
  const after = await page.$eval(".fbrand", (el) => el.innerHTML).catch((e) => "ERR:" + e.message);
  console.log("AFTER:", after.slice(-800));
  await browser.close();
})();

