const { chromium } = require("playwright");
const BASE = "http://localhost:3033";

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto(BASE + "/nxm", { waitUntil: "load", timeout: 30000 });
  await page.waitForTimeout(1000);
  await page.fill("#nxm-foot-email", "not-an-email");
  await page.click(".nxm-foot-nl button[type=submit]");
  // Poll up to 20s for the button to stop being "Subscribing…"
  let html = "";
  for (let i = 0; i < 20; i++) {
    await page.waitForTimeout(1000);
    html = await page.$eval(".nxm-foot-nl", (el) => el.outerHTML).catch((e) => "ERR:" + e.message);
    if (!html.includes("Subscribing")) break;
  }
  console.log("FINAL:", html);
  await browser.close();
})();

